head.script:
// ===== 리턴 값 출력 영역 (body_bottom.xml inline 복사) =====
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};



scwin.onpageload = function () {
};



// 화면에서 실제로 펼쳐져 있는 패널을 내용 영역 높이로 판별한다.
scwin.visiblePanels = function () {
    var arrOpen = [];
    var arrPanel = ["panels1", "panels2", "panels3"];
    for (var i = 0; i < arrPanel.length; i++) {
        var objContent = document.getElementById(target1.id + "_panel_" + arrPanel[i] + "_panelContent_panelContent" + (i + 1));
        if (objContent !== null && objContent.getBoundingClientRect().height > 1) {
            arrOpen.push(arrPanel[i]);
        }
    }
    return (arrOpen.length === 0) ? "없음" : arrOpen.join(", ");
};



// 발생한 이벤트를 순서대로 기록한다.
scwin.gVar = { log : [] };

scwin.target1_onpanelunload = function (panelID, userID) {
    scwin.gVar.log.push("onpanelunload(" + panelID + ")");
};

scwin.target1_onpanelload = function (panelID, userID) {
    scwin.gVar.log.push("onpanelload(" + panelID + ")");
};



scwin.btn_run_onclick = function (e) {
    // 1) panels3 만 열린 상태를 만든다.
    //    independentPanel=false 라 한 패널을 열면 다른 패널이 닫히므로 순서대로 열어 panels3 만 남긴다.
    target1.setDisabledPanel("panels1", false);
    target1.openPanel("panels2");
    target1.openPanel("panels3");

    setTimeout(function () {
        var strBefore = scwin.visiblePanels();

        // 2) panels1 을 비활성으로 만든다.
        target1.setDisabledPanel("panels1", true);
        scwin.gVar.log = [];

        // 3) 비활성 패널에 openPanel 을 호출한다.
        target1.openPanel("panels1");

        setTimeout(function () {
            var strAfter = scwin.visiblePanels();
            var arrLog = scwin.gVar.log;

            scwin.setReturnValue("=====비활성 패널에 openPanel() 호출=====");
            scwin.setReturnValue("    호출 전 열린 패널 : " + strBefore);
            scwin.setReturnValue("    openPanel(\"panels1\") 호출 후 열린 패널 : " + strAfter);
            scwin.setReturnValue("    호출 중 발생한 이벤트 : " + (arrLog.length === 0 ? "없음" : arrLog.join(" / ")));
            scwin.setReturnValue("");

            scwin.setReturnValue("----- 판정 -----");
            if (strAfter === strBefore) {
                scwin.setReturnValue("비활성 패널의 openPanel() 이 차단되어 기존 상태가 그대로 유지된다");
            } else {
                scwin.setReturnValue("비활성 패널은 열리지 않았으나 열려 있던 다른 패널까지 닫혔다 (" + strBefore + " -> " + strAfter + ")");
            }
            scwin.setReturnValue("");
        }, 900);
    }, 900);
};
